import type { AllocationComparison } from "../operator";
import type { TreasuryRun, TreasuryRunParams } from "./treasury";
import { runAiTreasury } from "./treasury";

/**
 * Capital recycling: Linden receives the investor's capital today, allocates
 * it (treasury / infrastructure reserve / liquidity), recycles retained
 * trading profits into productive assets and regains the full capacity after
 * the term (identical with and without investor → excluded from the delta).
 *
 * No perpetual growth: cash generated by reinvested assets is NOT reinvested
 * again within the horizon.
 */

export interface CapitalAllocation {
  treasuryBps: number;
  infrastructureBps: number;
  liquidityBps: number;
}

export type AssetCategory = "MINING" | "SOLAR" | "DATA_CENTER" | "OTHER";

export interface ReinvestmentMix {
  MINING: number;
  SOLAR: number;
  DATA_CENTER: number;
  OTHER: number;
}

export interface AssetAssumptions {
  /** Mining: purchase price per new PH/s (cents). */
  miningCapexPerPh: number;
  miningDeploymentDelayMonths: number;
  /** Useful life for straight-line book value, per category (months). */
  usefulLifeMonths: Record<AssetCategory, number>;
  /** Cash yield p.a. of non-mining assets (bps of invested amount). Mining yield comes from the engine. */
  annualYieldBps: Record<Exclude<AssetCategory, "MINING">, number>;
}

export interface ReinvestmentResult {
  invested: number;
  newPh: number;
  cashGenerated: number;
  residualValue: number;
  /** cashGenerated + residualValue at the end of the term. */
  valueAtTerm: number;
  byCategory: Record<AssetCategory, { invested: number; cash: number; residual: number }>;
}

/**
 * Invest `amount` at `investMonth` (0-based) and value it at the end of the term.
 * `miningNetPerPhByMonth[m]` = net cash flow of 1 new PH/s in calendar month m
 * (from the mining engine at the new capacity's cost basis).
 */
export function reinvest(amount: number, investMonth: number, termMonths: number, mix: ReinvestmentMix, a: AssetAssumptions, miningNetPerPhByMonth: number[]): ReinvestmentResult {
  const total = mix.MINING + mix.SOLAR + mix.DATA_CENTER + mix.OTHER;
  if (Math.abs(total - 10_000) > 0.5) throw new RangeError("reinvestment mix must sum to 10000 bps");
  const byCategory = {} as ReinvestmentResult["byCategory"];
  let cash = 0, residual = 0, newPh = 0;
  const age = Math.max(0, termMonths - investMonth);
  const book = (inv: number, cat: AssetCategory) => inv * Math.max(0, 1 - age / a.usefulLifeMonths[cat]);

  for (const cat of ["MINING", "SOLAR", "DATA_CENTER", "OTHER"] as AssetCategory[]) {
    const inv = (amount * mix[cat]) / 10_000;
    let c = 0;
    if (cat === "MINING") {
      const ph = a.miningCapexPerPh > 0 ? inv / a.miningCapexPerPh : 0;
      newPh += ph;
      for (let m = investMonth + a.miningDeploymentDelayMonths; m < termMonths; m++) c += ph * (miningNetPerPhByMonth[m] ?? 0);
    } else {
      c = (inv * a.annualYieldBps[cat]) / 10_000 / 12 * Math.max(0, termMonths - investMonth);
    }
    const r = book(inv, cat);
    byCategory[cat] = { invested: inv, cash: c, residual: r };
    cash += c;
    residual += r;
  }
  return { invested: amount, newPh, cashGenerated: cash, residualValue: residual, valueAtTerm: cash + residual, byCategory };
}

export interface CombinedParams {
  /** Mining comparison for exactly 1 PH/s at the chosen price (investor + Linden case A/B). */
  mining: AllocationComparison;
  allocation: CapitalAllocation;
  /** Treasury settings; initialCapital and months are set here. */
  treasury: Omit<TreasuryRunParams, "initialCapital" | "months">;
  reinvestmentMix: ReinvestmentMix;
  assets: AssetAssumptions;
  miningNetPerPhByMonth: number[];
  termMonths: number;
}

export interface CombinedOutcome {
  /** All per 1 PH/s allocated to the investor. */
  investor: {
    miningCashflow: number;
    miningProfit: number;
    treasuryAttribution: number;
    treasuryShare: number;
    totalCashflow: number;
    totalProfit: number;
    /** totalProfit ÷ investment over the whole term (not annualised). */
    totalReturn: number;
    miningBreakEvenMonth: number | null;
    totalBreakEvenMonth: number | null;
  };
  linden: {
    upfrontCapital: number;
    salesAndPaymentCosts: number;
    netCapital: number;
    deployed: { treasury: number; infrastructure: number; liquidity: number };
    tradingGross: number;
    tradingCosts: number;
    tradingNetBeforeShare: number;
    investorShare: number;
    /** Linden's trading result after investor share (ending equity + recycled − deployed). */
    tradingResult: number;
    reinvestedAmount: number;
    reinvestmentGain: number;
    newPh: number;
    operatingContribution: number;
    /** Value at month 24 from the allocation incl. treasury and recycling. */
    value24: number;
    /** Case A: self-mining the PH/s without investor. */
    selfMining24: number;
    delta: number;
  };
  treasuryRun: TreasuryRun;
}

export function combine(p: CombinedParams): CombinedOutcome {
  const sum = p.allocation.treasuryBps + p.allocation.infrastructureBps + p.allocation.liquidityBps;
  if (sum !== 10_000) throw new RangeError("capital allocation must sum to 10000 bps");
  const price = p.mining.pricePerPh;
  const net = p.mining.linden.upfrontNet;
  const T = (net * p.allocation.treasuryBps) / 10_000;
  const I = (net * p.allocation.infrastructureBps) / 10_000;
  const L = (net * p.allocation.liquidityBps) / 10_000;

  const run = runAiTreasury({ ...p.treasury, initialCapital: T, months: p.termMonths });
  const infra = reinvest(I, 0, p.termMonths, p.reinvestmentMix, p.assets, p.miningNetPerPhByMonth);
  const recycledResults = run.recycled.map((r) => reinvest(r.amount, r.month, p.termMonths, p.reinvestmentMix, p.assets, p.miningNetPerPhByMonth));
  const recycledValue = recycledResults.reduce((s, r) => s + r.valueAtTerm, 0);
  const reinvestedAmount = I + run.recycledTotal;
  const reinvestmentGain = infra.valueAtTerm + recycledValue - reinvestedAmount;
  const newPh = infra.newPh + recycledResults.reduce((s, r) => s + r.newPh, 0);

  const value24 = run.endingEquity + run.recycledTotal - T // trading result
    + T + I + L // capital back (net of sales/payment)
    + reinvestmentGain
    + p.mining.linden.operatingContribution;

  // Investor cash: mining per month + treasury share at crystallisation months.
  const shareByMonth = new Map(run.months.filter((m) => m.investorShare > 0).map((m) => [m.month, m.investorShare]));
  let pos = -price, be: number | null = null;
  for (const m of p.mining.months) {
    const cash = m.investorNet + (shareByMonth.get(m.month) ?? 0);
    const before = pos;
    pos += cash;
    if (be === null && before < 0 && pos >= 0 && cash > 0) be = m.month - 1 + -before / cash;
  }

  const miningCashflow = p.mining.investor.cumulativeNet24;
  const totalCashflow = miningCashflow + run.investorShareTotal;
  return {
    investor: {
      miningCashflow,
      miningProfit: miningCashflow - price,
      treasuryAttribution: T,
      treasuryShare: run.investorShareTotal,
      totalCashflow,
      totalProfit: totalCashflow - price,
      totalReturn: (totalCashflow - price) / price,
      miningBreakEvenMonth: p.mining.investor.breakEvenMonth,
      totalBreakEvenMonth: be,
    },
    linden: {
      upfrontCapital: price,
      salesAndPaymentCosts: price - net,
      netCapital: net,
      deployed: { treasury: T, infrastructure: I, liquidity: L },
      tradingGross: run.grossProfit,
      tradingCosts: run.totalCosts,
      tradingNetBeforeShare: run.netProfit,
      investorShare: run.investorShareTotal,
      tradingResult: run.lindenNetResult,
      reinvestedAmount,
      reinvestmentGain,
      newPh,
      operatingContribution: p.mining.linden.operatingContribution,
      value24,
      selfMining24: p.mining.linden.caseA,
      delta: value24 - p.mining.linden.caseA,
    },
    treasuryRun: run,
  };
}

/** Gross trading return p.a. (bps) at which Linden's delta vs self-mining is zero; null if outside −50 %…+300 %. */
export function lindenBreakEvenTradingReturn(p: Omit<CombinedParams, "treasury"> & { treasury: Omit<TreasuryRunParams, "initialCapital" | "months" | "grossReturnBpsPerYear"> }): number | null {
  const at = (bps: number) => combine({ ...p, treasury: { ...p.treasury, grossReturnBpsPerYear: bps } }).linden.delta;
  let lo = -5_000, hi = 30_000;
  if (at(lo) > 0) return lo;
  if (at(hi) < 0) return null;
  for (let i = 0; i < 60; i++) {
    const mid = (lo + hi) / 2;
    if (at(mid) >= 0) hi = mid; else lo = mid;
  }
  return hi;
}

export interface InvestorTreasuryParams {
  /** Investor's upfront payment (cents). */
  investment: number;
  /** Share of the payment that remains after sales/payment costs (bps). */
  netCapitalBps: number;
  allocation: CapitalAllocation;
  treasury: Omit<TreasuryRunParams, "initialCapital" | "months">;
  termMonths: number;
}

/**
 * Investor-side view for the website: the treasury capital attributed to this
 * investment and the investor's share of REALISED positive net profit (HWM).
 * Never negative – losses stay with Linden and do not touch the mining result.
 */
export function investorTreasuryParticipation(p: InvestorTreasuryParams): { attribution: number; share: number; run: TreasuryRun } {
  const attribution = (((p.investment * p.netCapitalBps) / 10_000) * p.allocation.treasuryBps) / 10_000;
  const run = runAiTreasury({ ...p.treasury, initialCapital: attribution, months: p.termMonths });
  return { attribution, share: run.investorShareTotal, run };
}
